    },
    {
      "page": 23,
      "quote": "d’un avenant marquant l’augmentation de la capacité de la centrale de Karpowership de 220 à 335 MW à partir du 10 octobre 2023.",
      "label": "avenant marquant l’augmentation de la capacité de la centrale de Karpowership",
      "classification": "decision",
      "fields": {
        "amount": null,
